import { cn } from "@/lib/utils";
import {
  Input,
  InputGroup,
  type InputProps,
  useInputFocusState,
} from "@/components/ui/input";

// Types
export type TextareaInputProps = InputProps & {
  onFocus?: () => void;
  onBlur?: () => void;
  disabled?: boolean;
  invalid?: boolean;
};

// Components
export const TextareaInput = ({
  onFocus,
  onBlur,
  disabled,
  invalid,
  className,
  ...props
}: TextareaInputProps) => {
  const { isFocused, internalRef, handleFocus, handleBlur, handlePress } =
    useInputFocusState({ onBlur, onFocus });

  return (
    <InputGroup
      accessible={false}
      disabled={disabled}
      focused={isFocused}
      inputFocused={isFocused}
      invalid={invalid}
      onPress={handlePress}
    >
      <Input
        {...props}
        className={cn("min-h-24", className)}
        disabled={disabled}
        multiline
        onBlur={handleBlur}
        onFocus={handleFocus}
        ref={internalRef}
        scrollEnabled={false}
        textAlignVertical="top"
      />
    </InputGroup>
  );
};
